/**
 * Recurring Tasks (GAP-08) — detail/view page. v963 Phase 11 (Simulator).
 * Mirrors apps/platform/src/modules/pmis-gaps/pages/RecurringTaskDetailPage.jsx.
 * Details tab shows the template config; Audit tab is the mandatory Identity/
 * Classification/Record history card set (rule 63.1). Instance history is
 * read-only (instances are generated by the recurrence, not hand-created) and
 * lives on the Details tab so there's no separate "instances" route/file.
 * Creator name resolution reads public.users (platformDb) by auth_user_id — a
 * read-only shared identity lookup, same precedent as
 * simProjectMembershipService.js's enrichMembersWithProfiles().
 */
import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Pencil } from 'lucide-react'
import DetailAuditTabList from '@nidus/ui/DetailAuditTabList'
import AuditDetailsPanel from '@nidus/ui/AuditDetailsPanel'
import AuditCard from '@nidus/ui/AuditCard'
import AuditField from '@nidus/ui/AuditField'
import AuditTimestampPair from '@nidus/ui/AuditTimestampPair'
import { getRecurringTaskTemplate } from '../services/recurringTaskService'
import { platformDb } from '@nidus/supabase'

const INSTANCE_STATUS_LABEL = {
  pending: 'Pending',
  created: 'Created',
  skipped: 'Skipped',
  completed: 'Completed',
}

export default function RecurringTaskDetailPage() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [loading, setLoading] = useState(true)
  const [template, setTemplate] = useState(null)
  const [creatorName, setCreatorName] = useState('—')
  const [activeTab, setActiveTab] = useState('details')

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setLoading(true)
      const result = await getRecurringTaskTemplate(id)
      if (cancelled) return
      if (result.success) {
        setTemplate(result.data)
        if (result.data.created_by) {
          const { data: user } = await platformDb.from('users').select('full_name').eq('auth_user_id', result.data.created_by).maybeSingle()
          if (!cancelled && user?.full_name) setCreatorName(user.full_name)
        }
      }
      setLoading(false)
    })()
    return () => { cancelled = true }
  }, [id])

  if (loading) return <div className="p-8 text-gray-500 dark:text-gray-400">Loading…</div>
  if (!template) return <div className="p-8 text-gray-500 dark:text-gray-400">Recurring task template not found.</div>

  return (
    <div className="p-4 sm:p-6 max-w-3xl mx-auto space-y-6">
      <button type="button" onClick={() => navigate('..')} className="inline-flex items-center gap-1 text-sm text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200">
        <ArrowLeft className="h-4 w-4" />
        Back to Recurring Tasks
      </button>

      <div className="flex items-start justify-between gap-3">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{template.template_name}</h1>
        <button type="button" onClick={() => navigate('edit')} className="inline-flex items-center gap-2 px-3 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-900 dark:text-gray-100 rounded-lg text-sm font-medium">
          <Pencil className="h-4 w-4" />
          Edit
        </button>
      </div>

      <DetailAuditTabList activeTab={activeTab} onChange={setActiveTab} ariaLabel="Recurring task template sections" />

      {activeTab === 'details' ? (
        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-5 space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <p className="text-xs uppercase text-gray-400 mb-1">Entity type</p>
                <p className="text-sm text-gray-700 dark:text-gray-300 capitalize">{template.entity_type?.replace(/_/g, ' ')}</p>
              </div>
              <div>
                <p className="text-xs uppercase text-gray-400 mb-1">Recurrence pattern</p>
                <p className="text-sm text-gray-700 dark:text-gray-300 capitalize">{template.recurrence_pattern}</p>
              </div>
              <div>
                <p className="text-xs uppercase text-gray-400 mb-1">Next run</p>
                <p className="text-sm text-gray-700 dark:text-gray-300">{template.schedule?.next_run_at ? new Date(template.schedule.next_run_at).toLocaleString() : '—'}</p>
              </div>
              <div>
                <p className="text-xs uppercase text-gray-400 mb-1">Status</p>
                <span className={`inline-flex px-2 py-1 rounded-full text-xs font-medium ${template.is_active ? 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>
                  {template.is_active ? 'Active' : 'Inactive'}
                </span>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-5">
            <h2 className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-3">Instance history</h2>
            {template.instances.length === 0 ? (
              <p className="text-sm text-gray-500 dark:text-gray-400">No instances generated yet.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs uppercase text-gray-400">
                      <th className="py-2 pr-4">Scheduled for</th>
                      <th className="py-2 pr-4">Status</th>
                      <th className="py-2 pr-4">Generated entity</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                    {template.instances.map((inst) => (
                      <tr key={inst.id}>
                        <td className="py-2 pr-4 text-gray-700 dark:text-gray-300">{inst.scheduled_for}</td>
                        <td className="py-2 pr-4 text-gray-700 dark:text-gray-300">{INSTANCE_STATUS_LABEL[inst.instance_status] || inst.instance_status}</td>
                        <td className="py-2 pr-4 text-gray-500 dark:text-gray-400">{inst.generated_entity_type || '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      ) : (
        <AuditDetailsPanel description="Who created or changed this recurring task template.">
          <AuditCard title="Identity">
            <AuditField label="Template" value={template.template_name} />
            <AuditField label="Entity type" value={template.entity_type} />
          </AuditCard>
          <AuditCard title="Classification">
            <AuditField label="Recurrence pattern" value={template.recurrence_pattern} />
            <AuditField label="Ends" value={template.end_condition?.replace(/_/g, ' ')} />
          </AuditCard>
          <AuditCard title="Record history">
            <AuditField label="Created by" value={creatorName} />
            <AuditTimestampPair dateLabel="Created at" value={template.created_at} />
            <AuditTimestampPair dateLabel="Updated at" value={template.updated_at} />
          </AuditCard>
        </AuditDetailsPanel>
      )}
    </div>
  )
}
